// FIXED TEMPLATE FILLER — not AI. Substitutes only owner_first_name + business_name.
// This message ASKS; it does NOT deliver a page. Demo link is ALWAYS the showcase URL.
const p = $('Get Prospect').item.json[0];
const biz = p.business_name;
const fn = (p.owner_first_name || (p.raw_data && p.raw_data.owner_first_name) || '').trim();
// If first name unknown, the whole opener uses the business name instead.
const opener = fn
  ? fn + ' \u2014 Christiaan from Streamline here. Quick one.'
  : biz + ' \u2014 Christiaan from Streamline here. Quick one.';
const text = [
  opener,
  '',
  "Not gonna lie, this is a pitch \u2014 but a good one that's gonna cost you nothing, so hear me out.",
  '',
  "I'm sure you already know this, but a lot of salons spend half their day managing bookings \u2014 phones going crazy, going back and forth on calls and WhatsApp to confirm times. I build free booking systems that make it easier to manage on your side and easier for clients to book on theirs.",
  '',
  'Quick look at one I built for a lash studio: https://booking-page-beta.vercel.app/?biz=showcase-lash-studio',
  '',
  'Happy to build one for ' + biz + " too. Here comes the catch \u2014 all I ask is a quick Google review once you've used it and you're happy.",
  '',
  "Let me know if that sounds like something you'd want \u2014 if not, no worries.",
  '',
  '\u2014 Christiaan from Streamline'
].join('\n');
return [{ json: { prospect_id: p.id, business_name: biz, draft_text: text } }];

